function LibraryToolbar({query,setQuery,tag,setTag,category,setCategory,children}:{query:string;setQuery:(q:string)=>void;tag:string;setTag:(q:string)=>void;category:string;setCategory:(q:string)=>void;children?:ReactNode}){return <div className="library-toolbar"><div className="search-box"><Icon name="search" size={18}/><input aria-label="搜索库" placeholder="搜索名称、正文或关键词" value={query} onChange={e=>setQuery(e.target.value)}/></div><input className="filter-input" aria-label="筛选标签" placeholder="标签" value={tag} onChange={e=>setTag(e.target.value)}/><input className="filter-input" aria-label="筛选分类" placeholder="分类" value={category} onChange={e=>setCategory(e.target.value)}/>{children}</div>;}
function useLibraryFilter(items:Doc[]){const [query,setQuery]=useState(''),[tag,setTag]=useState(''),[category,setCategory]=useState(''),[archived,setArchived]=useState(false);const filtered=items.filter(x=>!!x.archived===archived&&display(x).toLowerCase().includes(query.toLowerCase())&&(!tag||(x.tags||[]).some((t:string)=>t.includes(tag)))&&(!category||(x.category||'').includes(category)));return {query,setQuery,tag,setTag,category,setCategory,archived,setArchived,filtered};}
